function Button({children,onClick,kind='',disabled=false,title='',className='',type='button',tiny=false}:{children:ReactNode;onClick?:(event:any)=>void;kind?:string;disabled?:boolean;title?:string;className?:string;type?:'button'|'submit';tiny?:boolean}){return <button type={type} title={title} disabled={disabled} onClick={onClick} className={`btn ${kind} ${tiny?'tiny':''} ${className}`}>{children}</button>}
