function PageHead({title,help,actions}:{title:string;help:string;actions?:ReactNode}){return <div className="page-head"><div><div className="eyebrow">PHARMACY DATA WORKSPACE</div><h1 className="page-title">{title}</h1><p className="help-line">What this screen does: {help}</p></div>{actions&&<div className="page-head-actions">{actions}</div>}</div>}
