 const getStock=(p:string,s?:string)=>stock.filter(x=>x.productId===p&&(!s||x.storeId===s)).reduce((a,x)=>a+x.qty,0);
 const getSales=(p:string,monthsBack:number,storeId?:string,mode=averageMode)=>{const list=seedSales.filter(x=>x.productId===p&&(!storeId||x.storeId===storeId));const included=months.slice(-3).map((month,i)=>list.filter(x=>x.month===month).reduce((n,x)=>n+x.sales-x.returns,0)*(mode==='rolling'&&i===0?29/30:1));return included.reduce((a,x)=>a+x,0)/monthsBack};
