  const exportSupplierWorkbook=(supplierId?:string)=>{if(!supplierId){const rows=seedSuppliers.filter(s=>s.name.toLowerCase().includes(supplierSearch.toLowerCase())).map(s=>{const related=products.filter(p=>seedPurchases.some(x=>x.productId===p.id&&x.supplierId===s.id));return {'Supplier code':s.id,'Supplier':s.name,'Products supplied':related.length,'Current stock across products':related.reduce((n,p)=>n+productStats(p).qty,0),'Most recent purchase':seedPurchases.filter(x=>x.supplierId===s.id).sort((a,b)=>b.date.localeCompare(a.date))[0]?.date||''}});exportXlsx('filtered-suppliers.xlsx','Suppliers',rows);return}const related=products.filter(p=>seedPurchases.some(x=>x.productId===p.id&&x.supplierId===supplierId));const rows=related.map(p=>{const recent=seedPurchases.filter(x=>x.productId===p.id&&x.supplierId===supplierId).sort((a,b)=>b.date.localeCompare(a.date))[0];const prices=Object.fromEntries(seedSuppliers.map(s=>{const latest=seedPurchases.filter(x=>x.productId===p.id&&x.supplierId===s.id).sort((a,b)=>b.date.localeCompare(a.date))[0];return [`Last MRP · ${s.name}`,latest?.mrp??'']}));return {'Product code':p.id,'Product':p.name,'Stock':productStats(p).qty,'Last-month net sales':productStats(p).last,'3-month average':Number(productStats(p).avg.toFixed(2)),'Supplier purchase qty':recent?.qty??'','Last purchase date':recent?.date??'',...prices}});exportXlsx(`${seedSuppliers.find(s=>s.id===supplierId)?.name.toLowerCase().replaceAll(' ','-')||'supplier'}-product-details.xlsx`,'Products & supplier MRP',rows)};
 const processFile=async(file:File,override=false)=>{if(role!=='Admin'&&role!=='Manager'){notify('Not available for this role');return}const duplicate=batches.find(b=>b.file===file.name);if(duplicate&&!override){setModal({title:'Duplicate file detected',body:<div><p><b>{file.name}</b> already appears in batch history.</p><p className="small-note">Block this upload, or override as Admin to create a separate batch.</p><div className="modal-actions"><Button onClick={()=>{setModal(null);notify('Duplicate upload blocked')}}>Block upload</Button><Button kind="primary" disabled={role!=='Admin'} title={role!=='Admin'?'Not available for this role':''} onClick={()=>{setModal(null);void processFile(file,true)}}>Override as Admin</Button></div></div>});return}
 let wb:XLSX.WorkBook;try{wb=XLSX.read(await file.arrayBuffer(),{type:'array'})}catch{const fail:Batch={id:`IB-${Date.now()}`,file:file.name,type:'Unrecognised',status:'Failed',rows:0,loaded:0,rejected:0,uploadedBy:role,time:time(),errors:[{row:0,column:'Workbook',message:'Could not read this file as an Excel workbook. Upload a valid .xlsx file.'}]};setBatches(x=>[fail,...x]);return}
  const sheet=wb.Sheets[wb.SheetNames[0]];const rows=XLSX.utils.sheet_to_json<Record<string,unknown>>(sheet,{defval:''});const headers=Object.keys(rows[0]||{}).map(x=>x.toLowerCase());const identify=()=>{if(headers.some(x=>/return/.test(x)))return'Sales Return';if(headers.some(x=>/supplier|voucher/.test(x))&&headers.some(x=>/qty|quantity/.test(x)))return'Purchase';if(headers.some(x=>/stock|balance/.test(x)))return'Stock';if(headers.some(x=>/sales/.test(x)))return'Sales';return'Unrecognised'};const type=identify();const required=type==='Stock'?['product','store','stock','as of']:type==='Purchase'?['product','supplier','qty','date']:type==='Sales Return'?['product','store','month','return']:type==='Sales'?['product','store','month','sales']:[];const errs:{row:number;column:string;message:string}[]=[];if(type==='Unrecognised')errs.push({row:1,column:'Headers',message:'Could not identify report type from the column headers. Include product plus Sales, Stock, Supplier/Qty or Return columns.'});else required.filter(x=>!headers.some(h=>h.includes(x))).forEach(x=>errs.push({row:1,column:x,message:`Required column containing “${x}” is missing`}));const requiredHeaders=required.map(token=>headers.find(h=>h.includes(token))).filter((x):x is string=>!!x);rows.forEach((row,index)=>{for(const key of Object.keys(row)){const value=row[key];const lower=key.toLowerCase();if(requiredHeaders.includes(lower)&&(value===null||value===undefined||String(value).trim()===''))errs.push({row:index+2,column:key,message:'Required value is empty'});if(/qty|quantity|sales|stock|return|mrp|price|amount/i.test(key)&&value!==''&&value!==null&&value!==undefined&&(typeof value==='string'&&value.trim()===''||!Number.isFinite(Number(value))))errs.push({row:index+2,column:key,message:'Expected a numeric value'});if(/date|month|as of/i.test(key)&&value!==''&&value!==null&&value!==undefined){const valid=value instanceof Date?!Number.isNaN(value.getTime()):typeof value==='number'?!!XLSX.SSF.parse_date_code(value):!Number.isNaN(Date.parse(String(value)));if(!valid)errs.push({row:index+2,column:key,message:'Expected a valid date or reporting month'})}}});const loaded=Math.max(0,rows.length-errs.filter(e=>e.row>1).length);const batch:Batch={id:`IB-${Date.now()}`,file:file.name,type,status:type==='Unrecognised'?'Failed':errs.length?'Completed with errors':'Queued',rows:rows.length,loaded:type==='Unrecognised'?0:loaded,rejected:errs.filter(e=>e.row>1).length,uploadedBy:role,time:time(),errors:errs};setBatches(x=>[batch,...x]);setSelectedBatch(batch);if(type!=='Unrecognised'){setImportProgress(batch.id);let step=0;const stages=['Parse','Validate','Normalize','Match','Load'];const tick=()=>{step++;if(step<stages.length){setTimeout(tick,550)}else{setBatches(old=>old.map(b=>b.id===batch.id?{...b,status:errs.length?'Completed with errors':'Completed',loaded:rows.length-errs.filter(e=>e.row>1).length}:b));setImportProgress('');stampAudit(`Import processed: ${file.name}`);notify(`Processed ${rows.length} rows with ${errs.length} validation issue${errs.length===1?'':'s'}`)}};setTimeout(tick,450)}
 };
